import { cx } from '@/ui';
import { BRAND_RADIUS, BRAND_VIEW, HF_PATH, ROOF_PATH, ROOF_WIDTH } from './brandMark.generated';
import s from './BrandMark.module.css';

export interface BrandMarkProps {
  /** Side in px (sidebar 36, login 56). */
  size?: number;
  className?: string;
}

/**
 * The «Home Fit» mark — lavender roof over «HF» on the ink square, the same drawing as the app icon
 * (paths generated by scripts/gen-icons.mjs). Brand colours are fixed in both themes; decorative.
 */
export function BrandMark({ size = 36, className }: BrandMarkProps) {
  return (
    <svg
      className={cx(s.mark, className)}
      width={size}
      height={size}
      viewBox={`0 0 ${BRAND_VIEW} ${BRAND_VIEW}`}
      aria-hidden="true"
      focusable="false"
    >
      <rect width={BRAND_VIEW} height={BRAND_VIEW} rx={BRAND_RADIUS} fill="#1E2229" />
      <path
        d={ROOF_PATH}
        fill="none"
        stroke="#B9A8EE"
        strokeWidth={ROOF_WIDTH}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <path d={HF_PATH} fill="#F7F9FB" />
    </svg>
  );
}
